#!/usr/bin/env node
/* ===========================================================================
   GALLA - PARTNER WITH US PAGE (/partner)
   ---------------------------------------------------------------------------
   Run this from the project root (the folder that has package.json):

       node partner.mjs

   What it does:
     1. Creates the  components/partner/  folder
     2. Writes  app/partner/page.js  (any existing file is backed up as .bak)
     3. Adds the partner.css import to app/globals.css if it is not there yet

   Nothing else is touched. Safe to run more than once.

   If this prints English messages, you are running the current version.
   =========================================================================== */

import fs from "node:fs";
import path from "node:path";

const root = process.cwd();

if (!fs.existsSync(path.join(root, "package.json"))) {
  console.error("\n  Stop - this does not look like the project root.");
  console.error("  Change into the folder that has package.json and run it again.\n");
  process.exit(1);
}

const FILES = {
  "components/partner/AreYouACaOrTaxProfessional.js": "// ===========================================================================\n// SECTION 3  -  \"Are you a CA or tax professional? This is for you.\"\n// Four tick points, artwork and a CTA\n// IMAGE: content.js -> ca.img\n// ===========================================================================\n\nimport Link from \"next/link\";\nimport Reveal from \"@/components/Reveal\";\nimport Shot from \"./Shot\";\n\nexport default function AreYouACaOrTaxProfessional({ ca }) {\n  return (\n    <section className=\"section section--wash\">\n      <div className=\"wrap artsplit\">\n        <Reveal>\n          <span className=\"eyebrow\">{ca.eyebrow}</span>\n          <h2>{ca.h2}</h2>\n          <p className=\"lead\">{ca.lead}</p>\n\n          <ul className=\"pt-points\">\n            {ca.points.map(([t, d], i) => (\n              <li key={t} style={{ animationDelay: `${i * 90}ms` }}>\n                <span className=\"pt-points__tick\" aria-hidden=\"true\">\n                  <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.8\" strokeLinecap=\"round\" strokeLinejoin=\"round\">\n                    <path d=\"M5 13l4 4L19 7\" />\n                  </svg>\n                </span>\n                <div>\n                  <strong>{t}</strong>\n                  <p>{d}</p>\n                </div>\n              </li>\n            ))}\n          </ul>\n\n          <Link href={ca.cta[1]} className=\"btn btn--primary\">\n            {ca.cta[0]} <span aria-hidden=\"true\">&rarr;</span>\n          </Link>\n          <p className=\"pt-foot\">{ca.foot}</p>\n        </Reveal>\n\n        <Reveal className=\"artsplit__art\" delay={140}>\n          <Shot src={ca.img} art={ca.art} label={ca.imgLabel} alt={ca.h2} />\n        </Reveal>\n      </div>\n    </section>\n  );\n}\n",
  "components/partner/Art.js": "// ===========================================================================\n// PARTNER PAGE ARTWORK\n// ---------------------------------------------------------------------------\n// SVG drawings written in code. content.js picks one with  art: \"...\"\n// The full list of names is at the bottom, in Art().\n// To use a real photo instead, set  img: \"/my-photo.png\"  in content.js.\n// ===========================================================================\n\n/* --- CA partner dashboard --------------------------------------------- */\nexport function CaArt() {\n  return (\n    <svg className=\"art\" viewBox=\"0 0 420 300\" role=\"img\" aria-label=\"Partner dashboard with earnings\">\n      <circle className=\"art__blob\" cx=\"350\" cy=\"62\" r=\"52\" fill=\"var(--wash)\" />\n\n      {/* laptop */}\n      <rect x=\"54\" y=\"52\" width=\"252\" height=\"156\" rx=\"10\" fill=\"#fff\" stroke=\"var(--ink)\" strokeWidth=\"3\" />\n      <rect x=\"68\" y=\"66\" width=\"224\" height=\"128\" rx=\"6\" fill=\"var(--wash)\" />\n      <rect x=\"68\" y=\"66\" width=\"224\" height=\"22\" rx=\"6\" fill=\"var(--ledger)\" />\n      <rect x=\"80\" y=\"74\" width=\"54\" height=\"6\" rx=\"3\" fill=\"#fff\" opacity=\".85\" />\n\n      {/* earnings card */}\n      <rect x=\"82\" y=\"100\" width=\"96\" height=\"52\" rx=\"8\" fill=\"#fff\" />\n      <rect x=\"94\" y=\"112\" width=\"34\" height=\"6\" rx=\"3\" fill=\"var(--ink)\" opacity=\".35\" />\n      <text x=\"94\" y=\"140\" fill=\"var(--ledger)\" fontSize=\"20\" fontWeight=\"700\" fontFamily=\"system-ui, sans-serif\">\n        ₹\n      </text>\n      <rect x=\"110\" y=\"130\" width=\"46\" height=\"9\" rx=\"4.5\" fill=\"var(--ledger)\" />\n\n      {/* mini chart */}\n      <rect x=\"190\" y=\"100\" width=\"90\" height=\"76\" rx=\"8\" fill=\"#fff\" />\n      <g fill=\"var(--ledger)\">\n        <rect x=\"202\" y=\"146\" width=\"12\" height=\"20\" rx=\"3\" />\n        <rect x=\"220\" y=\"134\" width=\"12\" height=\"32\" rx=\"3\" />\n        <rect x=\"256\" y=\"126\" width=\"12\" height=\"40\" rx=\"3\" />\n      </g>\n      <rect x=\"238\" y=\"116\" width=\"12\" height=\"50\" rx=\"3\" fill=\"var(--marigold)\" />\n\n      <rect x=\"82\" y=\"160\" width=\"96\" height=\"16\" rx=\"8\" fill=\"var(--marigold)\" opacity=\".55\" />\n      <path d=\"M34 208h292l16 26H18z\" fill=\"#fff\" stroke=\"var(--ink)\" strokeWidth=\"3\" strokeLinejoin=\"round\" />\n\n      <g className=\"art__float\">\n        <circle cx=\"344\" cy=\"176\" r=\"32\" fill=\"var(--ledger)\" />\n        <path d=\"M344 160v32M334 172l10-10 10 10\" fill=\"none\" stroke=\"#fff\" strokeWidth=\"4.4\" strokeLinecap=\"round\" strokeLinejoin=\"round\" />\n      </g>\n      <circle className=\"art__pulse\" cx=\"344\" cy=\"176\" r=\"12\" fill=\"var(--marigold)\" />\n    </svg>\n  );\n}\n\n/* --- Network of referred businesses ----------------------------------- */\nexport function NetworkArt() {\n  return (\n    <svg className=\"art\" viewBox=\"0 0 420 300\" role=\"img\" aria-label=\"Your network, connected\">\n      <circle className=\"art__blob\" cx=\"72\" cy=\"66\" r=\"50\" fill=\"var(--wash)\" />\n      <g stroke=\"var(--ledger)\" strokeWidth=\"3\" strokeDasharray=\"7 7\" fill=\"none\" opacity=\".55\">\n        <path d=\"M210 150 96 78M210 150l114-72M210 150 96 226M210 150l114 76\" />\n      </g>\n      {[\n        [96, 78],\n        [324, 78],\n        [96, 226],\n        [324, 226],\n      ].map(([cx, cy], i) => (\n        <g key={i}>\n          <circle cx={cx} cy={cy} r=\"28\" fill=\"#fff\" stroke=\"var(--ink)\" strokeWidth=\"3\" />\n          <circle cx={cx} cy={cy - 6} r=\"8\" fill=\"var(--ledger)\" opacity=\".35\" />\n          <path d={`M${cx - 13} ${cy + 16}c3-10 8-14 13-14s10 4 13 14z`} fill=\"var(--ledger)\" opacity=\".35\" />\n        </g>\n      ))}\n      <circle className=\"art__pulse\" cx=\"210\" cy=\"150\" r=\"54\" fill=\"var(--marigold)\" opacity=\".22\" />\n      <g className=\"art__float\">\n        <circle cx=\"210\" cy=\"150\" r=\"42\" fill=\"var(--ledger)\" />\n        <path d=\"M194 150l10 11 22-23\" fill=\"none\" stroke=\"#fff\" strokeWidth=\"5.5\" strokeLinecap=\"round\" strokeLinejoin=\"round\" />\n      </g>\n    </svg>\n  );\n}\n\n/* --- Avatar, used until a real photo is added -------------------------- */\nexport function AvatarArt({ initial = \"G\" }) {\n  return (\n    <svg className=\"art pt-avatar\" viewBox=\"0 0 200 200\" role=\"img\" aria-label=\"Partner\">\n      <circle cx=\"100\" cy=\"100\" r=\"96\" fill=\"#fff\" opacity=\".9\" />\n      <circle cx=\"100\" cy=\"82\" r=\"34\" fill=\"var(--ledger)\" opacity=\".25\" />\n      <path d=\"M40 176c8-34 30-50 60-50s52 16 60 50z\" fill=\"var(--ledger)\" opacity=\".25\" />\n      <text x=\"100\" y=\"118\" textAnchor=\"middle\" fill=\"var(--ledger)\" fontSize=\"70\" fontWeight=\"700\" fontFamily=\"system-ui, sans-serif\">\n        {initial}\n      </text>\n    </svg>\n  );\n}\n\n/* ===========================================================================\n   PRODUCT CARD MOCKUPS\n   ---------------------------------------------------------------------------\n   Small UI screenshots drawn in code, shown at the top of each card in the\n   \"Why Your Clients Will Love Galla\" section.\n   =========================================================================== */\n\n// Shared frame so all four mockups line up the same way\nfunction Card({ children, title, tag, tagColor = \"var(--ledger)\" }) {\n  return (\n    <svg className=\"art pt-cardart\" viewBox=\"0 0 300 200\" role=\"img\" aria-label={title}>\n      <rect x=\"8\" y=\"8\" width=\"284\" height=\"184\" rx=\"12\" fill=\"#fff\" stroke=\"rgba(22,32,46,.12)\" strokeWidth=\"2\" />\n      {title && (\n        <>\n          <circle cx=\"26\" cy=\"30\" r=\"4\" fill={tagColor} />\n          <text x=\"38\" y=\"34\" fill=\"var(--ink)\" fontSize=\"11\" fontWeight=\"600\" fontFamily=\"system-ui, sans-serif\">\n            {title}\n          </text>\n        </>\n      )}\n      {tag && (\n        <>\n          <rect x=\"238\" y=\"21\" width=\"40\" height=\"18\" rx=\"5\" fill={tagColor} />\n          <text x=\"258\" y=\"34\" textAnchor=\"middle\" fill=\"#fff\" fontSize=\"10\" fontWeight=\"700\" fontFamily=\"system-ui, sans-serif\">\n            {tag}\n          </text>\n        </>\n      )}\n      {children}\n    </svg>\n  );\n}\n\nfunction Row({ y, label, value, valueColor = \"var(--ink)\", check }) {\n  return (\n    <>\n      <text x=\"26\" y={y} fill=\"rgba(22,32,46,.62)\" fontSize=\"10.5\" fontFamily=\"system-ui, sans-serif\">\n        {label}\n      </text>\n      <text x=\"274\" y={y} textAnchor=\"end\" fill={valueColor} fontSize=\"10.5\" fontWeight=\"600\" fontFamily=\"system-ui, sans-serif\">\n        {value}\n      </text>\n      {check && (\n        <path\n          d={`M${212} ${y - 7}l3 3.6 6-7`}\n          fill=\"none\"\n          stroke=\"var(--ledger)\"\n          strokeWidth=\"2\"\n          strokeLinecap=\"round\"\n          strokeLinejoin=\"round\"\n        />\n      )}\n    </>\n  );\n}\n\n/* 1. GST-ready invoice */\nexport function CardInvoiceArt() {\n  return (\n    <Card title=\"Galla Invoice\" tag=\"GST\">\n      <path d=\"M20 50h260\" stroke=\"rgba(22,32,46,.1)\" strokeWidth=\"1.5\" />\n      <Row y={74} label=\"GSTIN\" value=\"Verified\" valueColor=\"var(--ledger)\" check />\n      <Row y={100} label=\"HSN Code\" value=\"8471\" />\n      <Row y={126} label=\"Tax @18%\" value=\"₹1,800\" />\n      <path d=\"M20 142h260\" stroke=\"rgba(22,32,46,.1)\" strokeWidth=\"1.5\" />\n      <Row y={166} label=\"Total\" value=\"₹11,800\" valueColor=\"var(--ledger)\" />\n    </Card>\n  );\n}\n\n/* 2. Auto GSTR reports */\nexport function CardGstrArt() {\n  return (\n    <Card title=\"GSTR Reports\">\n      <rect x=\"22\" y=\"48\" width=\"62\" height=\"24\" rx=\"6\" fill=\"var(--ledger)\" />\n      <text x=\"53\" y=\"64\" textAnchor=\"middle\" fill=\"#fff\" fontSize=\"10\" fontWeight=\"700\" fontFamily=\"system-ui, sans-serif\">\n        GSTR-1\n      </text>\n      <rect x=\"92\" y=\"48\" width=\"66\" height=\"24\" rx=\"6\" fill=\"rgba(14,107,82,.12)\" />\n      <text x=\"125\" y=\"64\" textAnchor=\"middle\" fill=\"var(--ledger)\" fontSize=\"10\" fontWeight=\"700\" fontFamily=\"system-ui, sans-serif\">\n        GSTR-3B\n      </text>\n\n      {[\n        [\"Sales\", 168, 0.92],\n        [\"Tax\", 138, 0.66],\n        [\"ITC\", 100, 0.42],\n      ].map(([label, w, o], i) => {\n        const y = 96 + i * 26;\n        return (\n          <g key={label}>\n            <text x=\"26\" y={y + 4} fill=\"rgba(22,32,46,.6)\" fontSize=\"10\" fontFamily=\"system-ui, sans-serif\">\n              {label}\n            </text>\n            <rect x=\"74\" y={y - 5} width=\"200\" height=\"9\" rx=\"4.5\" fill=\"rgba(22,32,46,.07)\" />\n            <rect x=\"74\" y={y - 5} width={w} height=\"9\" rx=\"4.5\" fill=\"var(--ledger)\" opacity={o} />\n          </g>\n        );\n      })}\n\n      <text x=\"26\" y=\"178\" fill=\"rgba(22,32,46,.45)\" fontSize=\"9.5\" fontFamily=\"system-ui, sans-serif\">\n        Ready before you ask\n      </text>\n    </Card>\n  );\n}\n\n/* 3. Instant data sharing */\nexport function CardShareArt() {\n  return (\n    <Card>\n      <circle cx=\"150\" cy=\"56\" r=\"21\" fill=\"rgba(14,107,82,.1)\" />\n      <g stroke=\"var(--ledger)\" strokeWidth=\"2\" fill=\"none\" strokeLinecap=\"round\">\n        <circle cx=\"157\" cy=\"49\" r=\"4\" fill=\"var(--ledger)\" stroke=\"none\" />\n        <circle cx=\"143\" cy=\"57\" r=\"4\" fill=\"var(--ledger)\" stroke=\"none\" />\n        <circle cx=\"157\" cy=\"64\" r=\"4\" fill=\"var(--ledger)\" stroke=\"none\" />\n        <path d=\"M147 55l7-4M147 59l7 4\" />\n      </g>\n\n      <text x=\"150\" y=\"98\" textAnchor=\"middle\" fill=\"var(--ink)\" fontSize=\"12\" fontWeight=\"700\" fontFamily=\"system-ui, sans-serif\">\n        P&amp;L Report\n      </text>\n\n      <g>\n        <rect x=\"70\" y=\"112\" width=\"70\" height=\"46\" rx=\"10\" fill=\"rgba(14,107,82,.08)\" />\n        <rect x=\"93\" y=\"122\" width=\"24\" height=\"18\" rx=\"4\" fill=\"var(--ledger)\" />\n        <text x=\"105\" y=\"152\" textAnchor=\"middle\" fill=\"rgba(22,32,46,.65)\" fontSize=\"9\" fontFamily=\"system-ui, sans-serif\">\n          WhatsApp\n        </text>\n      </g>\n      <g>\n        <rect x=\"160\" y=\"112\" width=\"70\" height=\"46\" rx=\"10\" fill=\"rgba(242,162,12,.14)\" />\n        <rect x=\"183\" y=\"122\" width=\"24\" height=\"18\" rx=\"4\" fill=\"var(--marigold)\" />\n        <text x=\"195\" y=\"152\" textAnchor=\"middle\" fill=\"rgba(22,32,46,.65)\" fontSize=\"9\" fontFamily=\"system-ui, sans-serif\">\n          PDF\n        </text>\n      </g>\n    </Card>\n  );\n}\n\n/* 4. Errors caught at entry */\nexport function CardErrorArt() {\n  return (\n    <Card>\n      <rect x=\"26\" y=\"40\" width=\"248\" height=\"34\" rx=\"8\" fill=\"rgba(198,40,40,.08)\" />\n      <circle cx=\"46\" cy=\"57\" r=\"7.5\" fill=\"none\" stroke=\"#c62828\" strokeWidth=\"2\" />\n      <path d=\"M46 53v5M46 61v.1\" stroke=\"#c62828\" strokeWidth=\"2\" strokeLinecap=\"round\" />\n      <text x=\"62\" y=\"61\" fill=\"#c62828\" fontSize=\"11\" fontWeight=\"600\" fontFamily=\"system-ui, sans-serif\">\n        Invalid HSN: 4802\n      </text>\n\n      <path d=\"M150 84v22M143 100l7 7 7-7\" fill=\"none\" stroke=\"rgba(22,32,46,.35)\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\" />\n\n      <rect x=\"26\" y=\"116\" width=\"248\" height=\"34\" rx=\"8\" fill=\"rgba(14,107,82,.1)\" />\n      <circle cx=\"46\" cy=\"133\" r=\"7.5\" fill=\"var(--ledger)\" />\n      <path d=\"M42.5 133l2.6 2.8 4.6-5.2\" fill=\"none\" stroke=\"#fff\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\" />\n      <text x=\"62\" y=\"137\" fill=\"var(--ledger)\" fontSize=\"11\" fontWeight=\"600\" fontFamily=\"system-ui, sans-serif\">\n        Corrected: 480210\n      </text>\n\n      <text x=\"150\" y=\"172\" textAnchor=\"middle\" fill=\"rgba(22,32,46,.45)\" fontSize=\"9.5\" fontStyle=\"italic\" fontFamily=\"system-ui, sans-serif\">\n        Validation check completed\n      </text>\n    </Card>\n  );\n}\n\n/* ===========================================================================\n   Names you can use in content.js as  art: \"...\"\n   =========================================================================== */\nexport default function Art({ name, initial }) {\n  switch (name) {\n    case \"ca\":\n      return <CaArt />;\n    case \"network\":\n      return <NetworkArt />;\n    case \"avatar\":\n      return <AvatarArt initial={initial} />;\n    case \"cardInvoice\":\n      return <CardInvoiceArt />;\n    case \"cardGstr\":\n      return <CardGstrArt />;\n    case \"cardShare\":\n      return <CardShareArt />;\n    case \"cardError\":\n      return <CardErrorArt />;\n    default:\n      return <CaArt />;\n  }\n}\n",
  "components/partner/EarningsCalculator.js": "// ===========================================================================\n// SECTION 8  -  \"Calculate What You Could Earn\"\n// ---------------------------------------------------------------------------\n// Moving the slider animates the numbers up instead of jumping.\n// The rate lives in content.js -> calc.perClientPerMonth (placeholder for now).\n// IMAGE: none\n// ===========================================================================\n\n\"use client\";\nimport { useEffect, useRef, useState } from \"react\";\nimport Reveal from \"@/components/Reveal\";\n\n// Eases the number to its new value instead of jumping straight there\nfunction useCountUp(target, ms = 420) {\n  const [n, setN] = useState(target);\n  const from = useRef(target);\n  const raf = useRef(0);\n\n  useEffect(() => {\n    const start = performance.now();\n    const a = from.current;\n    const b = target;\n\n    function tick(now) {\n      const t = Math.min(1, (now - start) / ms);\n      const eased = 1 - Math.pow(1 - t, 3);\n      setN(Math.round(a + (b - a) * eased));\n      if (t < 1) raf.current = requestAnimationFrame(tick);\n      else from.current = b;\n    }\n\n    raf.current = requestAnimationFrame(tick);\n    return () => cancelAnimationFrame(raf.current);\n  }, [target, ms]);\n\n  return n;\n}\n\nconst inr = (v) => \"₹\" + v.toLocaleString(\"en-IN\");\n\nexport default function EarningsCalculator({ calc }) {\n  const [clients, setClients] = useState(calc.start);\n\n  const monthly = clients * calc.perClientPerMonth;\n  const annual = monthly * 12;\n\n  const mShown = useCountUp(monthly);\n  const aShown = useCountUp(annual);\n\n  const pct = ((clients - calc.min) / (calc.max - calc.min)) * 100;\n\n  return (\n    <section className=\"section\">\n      <div className=\"wrap\">\n        <Reveal className=\"center\">\n          <span className=\"eyebrow\">{calc.eyebrow}</span>\n          <h2>{calc.h2}</h2>\n          <p className=\"lead\">{calc.lead}</p>\n        </Reveal>\n\n        <div className=\"pt-calc\">\n          <Reveal className=\"pt-calc__box\">\n            <h3>{calc.title}</h3>\n            <p className=\"pt-calc__sub\">{calc.sub}</p>\n\n            <label className=\"pt-calc__label\" htmlFor=\"pt-clients\">\n              {calc.label}\n              <strong>{clients}</strong>\n            </label>\n\n            <input\n              id=\"pt-clients\"\n              type=\"range\"\n              min={calc.min}\n              max={calc.max}\n              value={clients}\n              onChange={(e) => setClients(Number(e.target.value))}\n              className=\"pt-range\"\n              style={{ \"--pt-pct\": `${pct}%` }}\n            />\n            <div className=\"pt-calc__ends\">\n              <span>{calc.min}</span>\n              <span>{calc.max}</span>\n            </div>\n\n            <div className=\"pt-calc__out\">\n              <div>\n                <span>{calc.monthlyLabel}</span>\n                <strong>{inr(mShown)}</strong>\n              </div>\n              <div>\n                <span>{calc.annualLabel}</span>\n                <strong>{inr(aShown)}</strong>\n              </div>\n            </div>\n\n            <p className=\"pt-calc__note\">{calc.note}</p>\n          </Reveal>\n\n          <Reveal className=\"pt-get\" delay={140}>\n            <h3>{calc.getTitle}</h3>\n            <ul>\n              {calc.get.map((g, i) => (\n                <li key={g} style={{ animationDelay: `${i * 80}ms` }}>\n                  <span aria-hidden=\"true\">\n                    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.8\" strokeLinecap=\"round\" strokeLinejoin=\"round\">\n                      <path d=\"M5 13l4 4L19 7\" />\n                    </svg>\n                  </span>\n                  {g}\n                </li>\n              ))}\n            </ul>\n          </Reveal>\n        </div>\n      </div>\n    </section>\n  );\n}\n",
  "components/partner/FrequentlyAskedQuestions.js": "// ===========================================================================\n// SECTION 9  -  \"Frequently Asked Questions\"\n// The questions live in content.js -> faqs\n// IMAGE: none\n// ===========================================================================\n\n\"use client\";\nimport { useState } from \"react\";\nimport Reveal from \"@/components/Reveal\";\n\nconst VISIBLE = 5;\n\nexport default function FrequentlyAskedQuestions({ faqs }) {\n  const [showAll, setShowAll] = useState(false);\n  const shown = showAll ? faqs : faqs.slice(0, VISIBLE);\n\n  return (\n    <section className=\"section\">\n      <div className=\"wrap\">\n        <Reveal className=\"center\">\n          <span className=\"eyebrow\">Common questions</span>\n          <h2>Questions about the partner program</h2>\n        </Reveal>\n\n        <div className=\"faq faq--home\">\n          {shown.map(([q, a]) => (\n            <details key={q} name=\"partner-faq\">\n              <summary>{q}</summary>\n              <p>{a}</p>\n            </details>\n          ))}\n        </div>\n\n        {faqs.length > VISIBLE && (\n          <div className=\"faq__actions\">\n            <button\n              type=\"button\"\n              className=\"btn btn--ghost\"\n              aria-expanded={showAll}\n              onClick={() => setShowAll(!showAll)}\n            >\n              {showAll ? \"View less FAQs\" : `View all ${faqs.length} FAQs`}\n              <span className={`faq__caret ${showAll ? \"up\" : \"\"}`} aria-hidden=\"true\" />\n            </button>\n          </div>\n        )}\n      </div>\n    </section>\n  );\n}\n",
  "components/partner/HeroBecomeAGallaPartner.js": "// ===========================================================================\n// SECTION 1  -  HERO + REGISTRATION FORM\n// Heading: \"Become a Galla Partner\"\n// The form itself lives in its own file -> PartnerForm.js\n// IMAGE: none (the form sits on the right side)\n// ===========================================================================\n\nimport PartnerForm from \"./PartnerForm\";\n\nexport default function HeroBecomeAGallaPartner({ hero }) {\n  return (\n    <section className=\"hero pt-hero\">\n      <div className=\"wrap\">\n        <p className=\"pt-crumb\">\n          {hero.crumb.map((c, i) => (\n            <span key={c}>\n              {i > 0 && <em aria-hidden=\"true\"> › </em>}\n              {c}\n            </span>\n          ))}\n        </p>\n\n        <div className=\"pt-hero__grid\">\n          <div className=\"pt-hero__copy\">\n            <span className=\"pill\">{hero.badge}</span>\n            <h1>{hero.h1}</h1>\n            <p className=\"pt-hero__h2\">{hero.h2}</p>\n            <p className=\"lead\">{hero.lead}</p>\n\n            <div className=\"pt-chips\">\n              {hero.chips.map((c, i) => (\n                <span key={c} style={{ animationDelay: `${i * 120}ms` }}>\n                  {c}\n                </span>\n              ))}\n            </div>\n\n            <ul className=\"pt-ticks\">\n              {hero.ticks.map((t) => (\n                <li key={t}>{t}</li>\n              ))}\n            </ul>\n          </div>\n\n          <div className=\"pt-hero__form\">\n            <PartnerForm form={hero.form} />\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n",
  "components/partner/Page.js": "// ===========================================================================\n// PARTNER PAGE - COMPOSITION\n// ---------------------------------------------------------------------------\n// This file only sets the order of the sections. To drop one, comment out\n// its line. All the text lives in content.js.\n// ===========================================================================\n\nimport CtaBand from \"@/components/CtaBand\";\nimport { CONTENT } from \"./content\";\n\nimport HeroBecomeAGallaPartner from \"./HeroBecomeAGallaPartner\";\nimport WhichKindOfPartnerAreYou from \"./WhichKindOfPartnerAreYou\";\nimport AreYouACaOrTaxProfessional from \"./AreYouACaOrTaxProfessional\";\nimport WhyYourClientsWillLoveGalla from \"./WhyYourClientsWillLoveGalla\";\nimport StartEarningInThreeSteps from \"./StartEarningInThreeSteps\";\nimport SuccessStoriesFromAcrossIndia from \"./SuccessStoriesFromAcrossIndia\";\nimport WhyBecomeAGallaPartner from \"./WhyBecomeAGallaPartner\";\nimport EarningsCalculator from \"./EarningsCalculator\";\nimport FrequentlyAskedQuestions from \"./FrequentlyAskedQuestions\";\n\nexport default function PartnerPage() {\n  const c = CONTENT;\n\n  return (\n    <>\n      <HeroBecomeAGallaPartner hero={c.hero} />\n      <WhichKindOfPartnerAreYou types={c.types} />\n      <AreYouACaOrTaxProfessional ca={c.ca} />\n      <WhyYourClientsWillLoveGalla product={c.product} />\n      <StartEarningInThreeSteps steps={c.steps} />\n      {/* Comment this line out until you have real partner stories */}\n      <SuccessStoriesFromAcrossIndia stories={c.stories} />\n      <WhyBecomeAGallaPartner why={c.why} />\n      <EarningsCalculator calc={c.calc} />\n      <FrequentlyAskedQuestions faqs={c.faqs} />\n      <CtaBand />\n    </>\n  );\n}\n\nexport const partnerMeta = {\n  title: \"Become a Galla Partner - referral program for CAs and resellers\",\n  description: CONTENT.hero.lead,\n};\n\nexport const partnerFaqs = CONTENT.faqs;\n",
  "components/partner/PartnerForm.js": "// ===========================================================================\n// Partner registration form\n// ---------------------------------------------------------------------------\n// FRONTEND ONLY for now - nothing is sent to a server.\n// When the backend exists, put the fetch() call where it says\n// \"BACKEND CALL GOES HERE\" below.\n// ===========================================================================\n\n\"use client\";\nimport { useState } from \"react\";\n\nexport default function PartnerForm({ form }) {\n  const [name, setName] = useState(\"\");\n  const [phone, setPhone] = useState(\"\");\n  const [err, setErr] = useState(\"\");\n  const [done, setDone] = useState(false);\n\n  function onSubmit(e) {\n    e.preventDefault();\n\n    if (!name.trim()) {\n      setErr(form.errName);\n      return;\n    }\n    if (!/^[6-9]\\d{9}$/.test(phone)) {\n      setErr(form.errPhone);\n      return;\n    }\n\n    setErr(\"\");\n\n    // ---- BACKEND CALL GOES HERE ------------------------------------------\n    // await fetch(\"/api/partner\", {\n    //   method: \"POST\",\n    //   headers: { \"Content-Type\": \"application/json\" },\n    //   body: JSON.stringify({ name, phone }),\n    // });\n    // ---------------------------------------------------------------------\n\n    setDone(true);\n  }\n\n  if (done) {\n    return (\n      <div className=\"pt-form pt-form--done\" id=\"partner-form\">\n        <span className=\"pt-form__tick\" aria-hidden=\"true\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.6\" strokeLinecap=\"round\" strokeLinejoin=\"round\">\n            <path d=\"M5 13l4 4L19 7\" />\n          </svg>\n        </span>\n        <p>{form.done}</p>\n      </div>\n    );\n  }\n\n  return (\n    <form className=\"pt-form\" id=\"partner-form\" onSubmit={onSubmit} noValidate>\n      <h2>{form.title}</h2>\n      <p className=\"pt-form__sub\">{form.sub}</p>\n\n      <label className=\"pt-field\">\n        <span>{form.nameLabel}</span>\n        <input\n          type=\"text\"\n          value={name}\n          onChange={(e) => setName(e.target.value)}\n          placeholder={form.namePlaceholder}\n          autoComplete=\"name\"\n        />\n      </label>\n\n      <label className=\"pt-field\">\n        <span>{form.phoneLabel}</span>\n        <div className=\"pt-field__phone\">\n          <em>+91</em>\n          <input\n            type=\"tel\"\n            inputMode=\"numeric\"\n            value={phone}\n            onChange={(e) => setPhone(e.target.value.replace(/\\D/g, \"\").slice(0, 10))}\n            placeholder={form.phonePlaceholder}\n            autoComplete=\"tel\"\n          />\n        </div>\n      </label>\n\n      {err && <p className=\"pt-form__err\">{err}</p>}\n\n      <button type=\"submit\" className=\"btn btn--primary pt-form__btn\">\n        {form.cta}\n      </button>\n    </form>\n  );\n}\n",
  "components/partner/Shot.js": "// ===========================================================================\n// Shot - image slot, used in this order:\n//   1. img: \"/x.png\" is set  -> that photo is shown\n//   2. otherwise art: \"ca\"   -> the code-drawn artwork from Art.js\n//   3. both empty            -> a dashed placeholder box\n// ===========================================================================\n\nimport Art from \"./Art\";\n\nexport default function Shot({ src, art, initial, alt = \"\", label = \"Image\", className = \"\" }) {\n  if (src) {\n    // eslint-disable-next-line @next/next/no-img-element\n    return <img src={src} alt={alt || label} className={`pt-shot__img ${className}`} loading=\"lazy\" />;\n  }\n  if (art) {\n    return (\n      <div className={`pt-art ${className}`}>\n        <Art name={art} initial={initial} />\n      </div>\n    );\n  }\n  return (\n    <div className={`pt-shot ${className}`} role=\"img\" aria-label={label}>\n      <span className=\"pt-shot__mark\" aria-hidden=\"true\" />\n      <span className=\"pt-shot__txt\">{label}</span>\n    </div>\n  );\n}\n",
  "components/partner/StartEarningInThreeSteps.js": "// ===========================================================================\n// SECTION 5  -  \"Start Earning in 3 Simple Steps\"\n// 01 Register  /  02 Refer  /  03 Earn\n// IMAGE: none\n// ===========================================================================\n\nimport Link from \"next/link\";\nimport Reveal from \"@/components/Reveal\";\n\nexport default function StartEarningInThreeSteps({ steps }) {\n  return (\n    <section className=\"section section--wash\">\n      <div className=\"wrap\">\n        <Reveal className=\"center\">\n          <span className=\"eyebrow\">{steps.eyebrow}</span>\n          <h2>{steps.h2}</h2>\n          <p className=\"lead\">{steps.lead}</p>\n        </Reveal>\n\n        <ol className=\"pt-steps\">\n          {steps.items.map(([t, d], i) => (\n            <Reveal as=\"li\" key={t} delay={i * 110} className=\"pt-step\">\n              <span className=\"pt-step__no\">{String(i + 1).padStart(2, \"0\")}</span>\n              <h3>{t}</h3>\n              <p>{d}</p>\n            </Reveal>\n          ))}\n        </ol>\n\n        <div className=\"center\">\n          <Link href={steps.cta[1]} className=\"btn btn--primary\">\n            {steps.cta[0]}\n          </Link>\n        </div>\n      </div>\n    </section>\n  );\n}\n",
  "components/partner/SuccessStoriesFromAcrossIndia.js": "// ===========================================================================\n// SECTION 6  -  \"Success Stories from Across India\"\n// ---------------------------------------------------------------------------\n// This is the design from the screenshot:\n//   - a bar of four region tabs (North / South / West / East)\n//   - each card is split in two: a coloured left panel (photo, name, role\n//     and the earnings badge) and a white right panel with the quote\n//   - switching tabs slides the cards back in\n//\n// COLOUR: the left panel uses the site green (--ledger). The screenshot used\n// red. To go red, change  --pt-accent  at the top of partner.css.\n//\n// TODO: everything here is a placeholder. Only use a real partner's name,\n//       photo and earnings once you have their written permission.\n// IMAGE: content.js -> stories.items[region][].img\n// ===========================================================================\n\n\"use client\";\nimport { useState } from \"react\";\nimport Link from \"next/link\";\nimport Reveal from \"@/components/Reveal\";\nimport Shot from \"./Shot\";\n\nexport default function SuccessStoriesFromAcrossIndia({ stories }) {\n  const [region, setRegion] = useState(stories.regions[0]);\n  const list = stories.items[region] ?? [];\n\n  return (\n    <section className=\"section\">\n      <div className=\"wrap\">\n        <Reveal className=\"center\">\n          <span className=\"eyebrow pt-eyebrow\">{stories.eyebrow}</span>\n          <h2 className=\"pt-underline\">{stories.h2}</h2>\n          <p className=\"lead\">{stories.lead}</p>\n        </Reveal>\n\n        {/* region tabs */}\n        <div className=\"pt-regions\" role=\"tablist\" aria-label=\"Region\">\n          {stories.regions.map((r) => (\n            <button\n              key={r}\n              type=\"button\"\n              role=\"tab\"\n              aria-selected={r === region}\n              className={`pt-region ${r === region ? \"is-on\" : \"\"}`}\n              onClick={() => setRegion(r)}\n            >\n              {r}\n            </button>\n          ))}\n        </div>\n\n        {/* the region in the key makes the entrance animation replay\n            every time the tab changes */}\n        <div className=\"pt-stories\" key={region}>\n          {list.map((s, i) => (\n            <article className=\"pt-story\" key={`${region}-${i}`} style={{ animationDelay: `${i * 110}ms` }}>\n              <div className=\"pt-story__side\">\n                <Shot\n                  src={s.img}\n                  art=\"avatar\"\n                  initial={s.initial}\n                  label={s.imgLabel}\n                  alt={s.name}\n                  className=\"pt-story__pic\"\n                />\n                <p className=\"pt-story__name\">{s.name}</p>\n                <p className=\"pt-story__role\">{s.role}</p>\n                <span className=\"pt-story__amount\">{s.amount}</span>\n              </div>\n              <div className=\"pt-story__body\">\n                <p>{s.quote}</p>\n              </div>\n            </article>\n          ))}\n        </div>\n\n        <div className=\"center pt-stories__cta\">\n          <Link href={stories.cta[1]} className=\"btn btn--primary\">\n            {stories.cta[0]}\n          </Link>\n        </div>\n      </div>\n    </section>\n  );\n}\n",
  "components/partner/WhichKindOfPartnerAreYou.js": "// ===========================================================================\n// SECTION 2  -  \"Which Kind of Partner Are You?\"\n// 4 cards: CA, Software Reseller, Retail Store, Hardware Store\n// ---------------------------------------------------------------------------\n// Uses the .pt-quad grid, which forces all four onto one row on desktop\n// instead of wrapping 3 + 1. Card styling is .pt-qcard in partner.css.\n// IMAGE: none (icons only)\n// ===========================================================================\n\nimport Reveal from \"@/components/Reveal\";\nimport MenuIcon from \"@/components/MenuIcon\";\n\nexport default function WhichKindOfPartnerAreYou({ types }) {\n  return (\n    <section className=\"section\">\n      <div className=\"wrap\">\n        <Reveal className=\"center\">\n          <span className=\"eyebrow pt-eyebrow\">{types.eyebrow}</span>\n          <h2>{types.h2}</h2>\n          <p className=\"lead\">{types.lead}</p>\n        </Reveal>\n\n        <div className=\"pt-quad\">\n          {types.items.map(([t, d, icon], i) => (\n            <Reveal key={t} delay={i * 90}>\n              <article className=\"pt-qcard\">\n                <span className=\"pt-qcard__bar\" aria-hidden=\"true\" />\n                <span className=\"pt-qcard__icon\">\n                  <MenuIcon name={icon} />\n                </span>\n                <h3>{t}</h3>\n                <p>{d}</p>\n              </article>\n            </Reveal>\n          ))}\n        </div>\n      </div>\n    </section>\n  );\n}\n",
  "components/partner/WhyBecomeAGallaPartner.js": "// ===========================================================================\n// SECTION 7  -  \"Why Become a Galla Partner?\"\n// 4 cards: Recurring Income, Fast Payout, Extensive Support, No Investment\n// ---------------------------------------------------------------------------\n// Uses the .pt-quad grid, which forces all four onto one row on desktop\n// instead of wrapping 3 + 1. Card styling is .pt-qcard in partner.css.\n// IMAGE: none (icons only)\n// ===========================================================================\n\nimport Reveal from \"@/components/Reveal\";\nimport MenuIcon from \"@/components/MenuIcon\";\n\nexport default function WhyBecomeAGallaPartner({ why }) {\n  return (\n    <section className=\"section section--wash\">\n      <div className=\"wrap\">\n        <Reveal className=\"center\">\n          <span className=\"eyebrow pt-eyebrow\">{why.eyebrow}</span>\n          <h2>{why.h2}</h2>\n          <p className=\"lead\">{why.lead}</p>\n        </Reveal>\n\n        <div className=\"pt-quad\">\n          {why.items.map(([t, d, icon], i) => (\n            <Reveal key={t} delay={i * 90}>\n              <article className=\"pt-qcard pt-qcard--num\" data-num={String(i + 1).padStart(2, \"0\")}>\n                <span className=\"pt-qcard__bar\" aria-hidden=\"true\" />\n                <span className=\"pt-qcard__icon\">\n                  <MenuIcon name={icon} />\n                </span>\n                <h3>{t}</h3>\n                <p>{d}</p>\n              </article>\n            </Reveal>\n          ))}\n        </div>\n      </div>\n    </section>\n  );\n}\n",
  "components/partner/WhyYourClientsWillLoveGalla.js": "// ===========================================================================\n// SECTION 4  -  \"Why Your Clients Will Love Galla?\"\n// ---------------------------------------------------------------------------\n// This is the design from the screenshot:\n//   - a small rounded pill above the heading (PRODUCT CONFIDENCE)\n//   - heading where the second half is highlighted and underlined\n//   - a centred sub-line\n//   - four cards, each with a small UI mockup on a tinted panel at the top\n//     and the title plus description below it\n//   - a centred button under the row\n//\n// The mockups are drawn in Art.js (cardInvoice, cardGstr, cardShare,\n// cardError). To swap one for a real screenshot, set that card's\n// img: \"/my-shot.png\" in content.js.\n// ===========================================================================\n\nimport Link from \"next/link\";\nimport Reveal from \"@/components/Reveal\";\nimport Shot from \"./Shot\";\n\nexport default function WhyYourClientsWillLoveGalla({ product }) {\n  const [head, highlight] = product.h2;\n\n  return (\n    <section className=\"section pt-product\">\n      <div className=\"wrap\">\n        <Reveal className=\"center\">\n          <span className=\"pt-pill\">{product.eyebrow}</span>\n          <h2 className=\"pt-product__h2\">\n            {head}\n            <span className=\"pt-mark\">{highlight}</span>\n          </h2>\n          <p className=\"lead\">{product.lead}</p>\n        </Reveal>\n\n        <div className=\"pt-cards\">\n          {product.items.map((it, i) => (\n            <Reveal key={it.title} delay={i * 90}>\n              <article className=\"pt-card\">\n                <div className=\"pt-card__shot\">\n                  <Shot src={it.img} art={it.art} label={it.imgLabel} alt={it.title} />\n                </div>\n                <h3>{it.title}</h3>\n                <p>{it.text}</p>\n              </article>\n            </Reveal>\n          ))}\n        </div>\n\n        {product.cta && (\n          <div className=\"center pt-cards__cta\">\n            <Link href={product.cta[1]} className=\"btn btn--primary\">\n              {product.cta[0]}\n            </Link>\n          </div>\n        )}\n      </div>\n    </section>\n  );\n}\n",
  "components/partner/content.js": "// ===========================================================================\n// PARTNER PAGE - ALL TEXT AND IMAGE PATHS\n// ---------------------------------------------------------------------------\n// Every section below is named after its heading, so the matching component\n// file is easy to find.\n//\n// IMAGES:\n//   Where  img: \"\"  is empty, the code-drawn artwork from Art.js is shown.\n//   To use a real photo instead, put the file in  public/  and set\n//   img: \"/my-photo.png\"  here. The drawing disappears automatically.\n//\n// TODO items - search \"TODO\" for the places that still need real data:\n//   - partner success stories (names, photos, earnings)\n//   - the per-client rate used by the earnings calculator\n// ===========================================================================\n\nexport const CONTENT = {\n  // -------------------------------------------------------------------------\n  // 1. HERO + FORM  ->  HeroBecomeAGallaPartner.js\n  // -------------------------------------------------------------------------\n  hero: {\n    crumb: [\"Home\", \"Become partner\"],\n    badge: \"Partner program\",\n    h1: \"Become a Galla Partner\",\n    // TODO: before publishing any income claim, confirm your real numbers.\n    //       Overstated earnings claims can cause legal trouble later.\n    h2: \"Turn your client network into monthly income\",\n    lead:\n      \"Recommend Galla to the businesses you already work with. Earn on every sale and every renewal, with nothing to invest upfront.\",\n    chips: [\"Zero investment\", \"Regular payouts\", \"Your own partner dashboard\"],\n    form: {\n      title: \"Become a partner\",\n      sub: \"Fill in the form and our team will call you within 24 hours.\",\n      nameLabel: \"Name\",\n      namePlaceholder: \"Your full name\",\n      phoneLabel: \"Phone\",\n      phonePlaceholder: \"10 digit mobile number\",\n      cta: \"Register Now\",\n      // The form is frontend only for now. Backend goes in PartnerForm.js\n      done: \"Thank you. We have your details and our team will call you shortly.\",\n      errName: \"Please enter your name\",\n      errPhone: \"Please enter a valid 10 digit mobile number\",\n    },\n    ticks: [\n      \"GST-compliant invoicing\",\n      \"Secure platform\",\n      \"Earn on every renewal\",\n      \"Free marketing material\",\n    ],\n  },\n\n  // -------------------------------------------------------------------------\n  // 2. PARTNER TYPES  ->  WhichKindOfPartnerAreYou.js\n  // -------------------------------------------------------------------------\n  types: {\n    eyebrow: \"Who can join\",\n    h2: \"Which Kind of Partner Are You?\",\n    lead: \"We have a programme for every professional background.\",\n    items: [\n      [\n        \"CA / Tax Consultant\",\n        \"Recommend Galla to the clients you already advise and earn on every renewal. Compliant software also adds to your professional credibility.\",\n        \"ledger\",\n      ],\n      [\n        \"Software Reseller / Distributor\",\n        \"Sell Galla subscriptions to local businesses and build a recurring book of business with regular settlements.\",\n        \"box\",\n      ],\n      [\n        \"Retail Store Owner\",\n        \"Help nearby shops handle billing, stock and GST. Stronger relationships, and extra income alongside your own counter.\",\n        \"basket\",\n      ],\n      [\n        \"Hardware Store Owner\",\n        \"Already connected to other local businesses? Point them to Galla and earn while you run your own shop.\",\n        \"tool\",\n      ],\n    ],\n  },\n\n  // -------------------------------------------------------------------------\n  // 3. CA SECTION  ->  AreYouACaOrTaxProfessional.js\n  // -------------------------------------------------------------------------\n  ca: {\n    eyebrow: \"For CA professionals\",\n    h2: \"Are you a CA or tax professional? This is for you.\",\n    lead:\n      \"You already advise your clients on compliance, GST and accounting. The Galla CA Partner Program turns that existing trust into a second income, with no extra work.\",\n    points: [\n      [\n        \"Your clients need this anyway\",\n        \"Galla handles GST billing, e-invoicing and accounting. Recommend something your clients already need, and earn on every renewal.\",\n      ],\n      [\n        \"Onboarding under your name\",\n        \"Share your own referral link. Clients sign up under your name, and every activation and payout shows in one dashboard.\",\n      ],\n      [\n        \"Recurring income, not one-time\",\n        \"You earn each time a referred client renews, not just on the first sale. As active clients grow, so does the income.\",\n      ],\n      [\n        \"Compliance-ready software\",\n        \"Galla produces GST-format bills and reports, so recommending it protects your professional credibility.\",\n      ],\n    ],\n    img: \"\",\n    art: \"ca\",\n    imgLabel: \"Partner dashboard\",\n    cta: [\"Join as a CA Partner\", \"#partner-form\"],\n    foot: \"Registration is free. You get your partner dashboard once approved.\",\n  },\n\n  // -------------------------------------------------------------------------\n  // 4. PRODUCT CONFIDENCE  ->  WhyYourClientsWillLoveGalla.js\n  // -------------------------------------------------------------------------\n  // Heading is split in two so the second half can be highlighted.\n  product: {\n    eyebrow: \"Product confidence\",\n    h2: [\"Why Your Clients Will \", \"Love Galla?\"],\n    lead:\n      \"Galla is a business accounting app built for Indian small businesses - GST billing, inventory and financial reporting in one place.\",\n    // Each card has a small UI mockup on top (drawn in Art.js) and text below.\n    items: [\n      {\n        title: \"GST-Ready Invoicing\",\n        text: \"GSTIN and HSN auto-validated. Compliant by default.\",\n        art: \"cardInvoice\",\n        img: \"\", // real screenshot goes here if you have one\n        imgLabel: \"GST invoice mockup\",\n      },\n      {\n        title: \"Auto GSTR Reports\",\n        text: \"GSTR-1 and GSTR-3B ready before you ask.\",\n        art: \"cardGstr\",\n        img: \"\",\n        imgLabel: \"GSTR reports mockup\",\n      },\n      {\n        title: \"Instant Data Sharing\",\n        text: \"Clients share P&L and ledgers directly from the app.\",\n        art: \"cardShare\",\n        img: \"\",\n        imgLabel: \"Data sharing mockup\",\n      },\n      {\n        title: \"Errors Caught at Entry\",\n        text: \"Wrong HSN codes are flagged before filing, not after.\",\n        art: \"cardError\",\n        img: \"\",\n        imgLabel: \"Error validation mockup\",\n      },\n    ],\n    cta: [\"Become a Partner\", \"#partner-form\"],\n  },\n\n  // -------------------------------------------------------------------------\n  // 5. THREE STEPS  ->  StartEarningInThreeSteps.js\n  // -------------------------------------------------------------------------\n  steps: {\n    eyebrow: \"How it works\",\n    h2: \"Start Earning in 3 Simple Steps\",\n    lead: \"No tech skills, no inventory, no upfront cost.\",\n    items: [\n      [\n        \"Register for free\",\n        \"Fill in the form above. Get approved within 24 hours and receive your partner link and dashboard access.\",\n      ],\n      [\n        \"Refer businesses\",\n        \"Share your link with clients, shop owners or your local network. They get a good billing app, you get credited for the referral.\",\n      ],\n      [\n        \"Earn into your bank\",\n        \"Settlements go straight to your bank account. Sales, renewals and payouts are all tracked in your dashboard.\",\n      ],\n    ],\n    cta: [\"Get Started Now\", \"#partner-form\"],\n  },\n\n  // -------------------------------------------------------------------------\n  // 6. SUCCESS STORIES  ->  SuccessStoriesFromAcrossIndia.js\n  // -------------------------------------------------------------------------\n  // TODO: everything here is a placeholder. Only use a real partner's name,\n  //       photo and earnings after you have their written permission.\n  stories: {\n    eyebrow: \"Partners\",\n    h2: \"Success Stories from Across India\",\n    lead: \"Real partner stories will appear here. These are placeholders for now.\",\n    regions: [\"North\", \"South\", \"West\", \"East\"],\n    items: {\n      North: [\n        {\n          name: \"Partner name\",\n          role: \"(Partner type)\",\n          amount: \"₹— / month\",\n          quote: \"The partner's story goes here. This is a placeholder.\",\n          initial: \"N\",\n          img: \"\",\n          imgLabel: \"Partner photo\",\n        },\n        {\n          name: \"Partner name\",\n          role: \"(Partner type)\",\n          amount: \"₹— / month\",\n          quote: \"The partner's story goes here. This is a placeholder.\",\n          initial: \"N\",\n          img: \"\",\n          imgLabel: \"Partner photo\",\n        },\n      ],\n      South: [\n        {\n          name: \"Partner name\",\n          role: \"(Partner type)\",\n          amount: \"₹— / month\",\n          quote: \"The partner's story goes here. This is a placeholder.\",\n          initial: \"S\",\n          img: \"\",\n          imgLabel: \"Partner photo\",\n        },\n        {\n          name: \"Partner name\",\n          role: \"(Partner type)\",\n          amount: \"₹— / month\",\n          quote: \"The partner's story goes here. This is a placeholder.\",\n          initial: \"S\",\n          img: \"\",\n          imgLabel: \"Partner photo\",\n        },\n      ],\n      West: [\n        {\n          name: \"Partner name\",\n          role: \"(Partner type)\",\n          amount: \"₹— / month\",\n          quote: \"The partner's story goes here. This is a placeholder.\",\n          initial: \"W\",\n          img: \"\",\n          imgLabel: \"Partner photo\",\n        },\n        {\n          name: \"Partner name\",\n          role: \"(Partner type)\",\n          amount: \"₹— / month\",\n          quote: \"The partner's story goes here. This is a placeholder.\",\n          initial: \"W\",\n          img: \"\",\n          imgLabel: \"Partner photo\",\n        },\n      ],\n      East: [\n        {\n          name: \"Partner name\",\n          role: \"(Partner type)\",\n          amount: \"₹— / month\",\n          quote: \"The partner's story goes here. This is a placeholder.\",\n          initial: \"E\",\n          img: \"\",\n          imgLabel: \"Partner photo\",\n        },\n        {\n          name: \"Partner name\",\n          role: \"(Partner type)\",\n          amount: \"₹— / month\",\n          quote: \"The partner's story goes here. This is a placeholder.\",\n          initial: \"E\",\n          img: \"\",\n          imgLabel: \"Partner photo\",\n        },\n      ],\n    },\n    cta: [\"Become a Partner\", \"#partner-form\"],\n  },\n\n  // -------------------------------------------------------------------------\n  // 7. WHY PARTNER  ->  WhyBecomeAGallaPartner.js\n  // -------------------------------------------------------------------------\n  why: {\n    eyebrow: \"The benefits\",\n    h2: \"Why Become a Galla Partner?\",\n    lead: \"A network you build once keeps paying you every year.\",\n    items: [\n      [\n        \"Recurring Income\",\n        \"Earn on the first sale and on every renewal after it, so the income grows steadily over time.\",\n        \"ledger\",\n      ],\n      [\"Fast Payout\", \"Settlements go directly to your bank account.\", \"download\"],\n      [\n        \"Extensive Support\",\n        \"Marketing material, training and a dedicated support team, so you are never working alone.\",\n        \"users\",\n      ],\n      [\n        \"No Investment Required\",\n        \"No stock to buy and no registration fee. Start with zero investment.\",\n        \"handshake\",\n      ],\n    ],\n  },\n\n  // -------------------------------------------------------------------------\n  // 8. CALCULATOR  ->  EarningsCalculator.js\n  // -------------------------------------------------------------------------\n  calc: {\n    eyebrow: \"Do the maths\",\n    h2: \"Calculate What You Could Earn\",\n    lead: \"Move the slider to see an estimate.\",\n    title: \"Earnings Calculator\",\n    sub: \"Your potential earnings as a Galla Partner\",\n    label: \"Number of clients\",\n    min: 1,\n    max: 100,\n    start: 10,\n    // TODO: this rate is a PLACEHOLDER. Put your real per-client monthly\n    //       commission here - both figures below are calculated from it.\n    perClientPerMonth: 400,\n    monthlyLabel: \"Monthly earnings\",\n    annualLabel: \"Annual earnings\",\n    note: \"This is only an estimate, not a guarantee. Actual earnings depend on the plan and on renewals.\",\n    getTitle: \"What You Get as a Galla Partner\",\n    get: [\n      \"A dedicated dashboard to track earnings\",\n      \"Digital marketing material and assets\",\n      \"Regular product training sessions\",\n      \"A personal relationship manager\",\n      \"Access to the partner community\",\n      \"Special incentives and bonuses\",\n    ],\n  },\n\n  // -------------------------------------------------------------------------\n  // 9. FAQ  ->  FrequentlyAskedQuestions.js\n  // -------------------------------------------------------------------------\n  faqs: [\n    [\n      \"What is the Galla Partner Program?\",\n      \"It is a referral programme. You introduce Galla to businesses and earn on every successful referral, both on the first sale and on renewals.\",\n    ],\n    [\n      \"Can I recommend Galla without becoming a full-time partner?\",\n      \"Yes. Many partners refer alongside their own work. There is no minimum target.\",\n    ],\n    [\n      \"How much can I earn as a Galla Partner?\",\n      \"It depends on how many clients you refer and how many of them renew. The calculator above is only an estimate, not a guarantee.\",\n    ],\n    [\n      \"Do I need to invest anything to join?\",\n      \"No. Registration is free, there is no stock to buy and no joining fee.\",\n    ],\n    [\n      \"Does recommending Galla create a conflict of interest?\",\n      \"Galla is business software your client would use anyway. Even so, it is worth checking the rules of your own professional body.\",\n    ],\n    [\n      \"When and how do I get paid?\",\n      \"After approval, settlements go straight to your bank account. Every payout is recorded in your partner dashboard.\",\n    ],\n    [\n      \"What happens after I register?\",\n      \"Our team contacts you within 24 hours. Once approved, you receive your partner link and dashboard.\",\n    ],\n  ],\n};\n",
  "components/partner/partner.css": "/* ==========================================================================\n   PARTNER PAGE CSS\n   Every class starts with \"pt-\" so nothing clashes with the other pages.\n   This file is imported from globals.css.\n   ========================================================================== */\n\n:root {\n  /* Accent colour: the left panel of the success-story cards, the pill\n     above the product heading and the highlighted words in it.\n     The screenshot used red - for red, set this to #e02a37. */\n  --pt-accent: var(--ledger, #0e6b52);\n  --pt-accent-soft: rgba(14, 107, 82, 0.08);\n}\n\n/* ---- Animations --------------------------------------------------------- */\n@keyframes pt-rise {\n  from {\n    opacity: 0;\n    transform: translateY(16px);\n  }\n  to {\n    opacity: 1;\n    transform: none;\n  }\n}\n@keyframes pt-slide {\n  from {\n    opacity: 0;\n    transform: translateY(22px) scale(0.985);\n  }\n  to {\n    opacity: 1;\n    transform: none;\n  }\n}\n@keyframes pt-grow {\n  from {\n    transform: scaleX(0);\n  }\n  to {\n    transform: scaleX(1);\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .pt-chips span,\n  .pt-points li,\n  .pt-story,\n  .pt-get li,\n  .pt-underline::after {\n    animation: none !important;\n    opacity: 1 !important;\n    transform: none !important;\n  }\n}\n\n/* ---- Image slot --------------------------------------------------------- */\n.pt-art {\n  display: block;\n  width: 100%;\n}\n.pt-art .art {\n  display: block;\n  width: 100%;\n  height: auto;\n  overflow: visible;\n}\n.pt-shot__img {\n  width: 100%;\n  height: auto;\n  display: block;\n  border-radius: 18px;\n}\n.pt-shot {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 0.6rem;\n  min-height: 200px;\n  padding: 1.4rem;\n  text-align: center;\n  border: 2px dashed rgba(14, 107, 82, 0.28);\n  border-radius: 18px;\n  background: var(--wash, #eef5f1);\n  color: rgba(22, 32, 46, 0.55);\n  font-size: 0.86rem;\n}\n.pt-shot__mark {\n  width: 34px;\n  height: 26px;\n  border-radius: 5px;\n  border: 2px solid rgba(14, 107, 82, 0.35);\n  position: relative;\n}\n.pt-shot__mark::after {\n  content: \"\";\n  position: absolute;\n  inset: auto 4px 4px 4px;\n  height: 9px;\n  border-radius: 3px;\n  background: rgba(242, 162, 12, 0.5);\n}\n\n/* ---- 1. Hero ------------------------------------------------------------ */\n.pt-hero {\n  padding-bottom: 3.4rem;\n}\n.pt-crumb {\n  margin: 0 0 1.2rem;\n  font-size: 0.84rem;\n  color: rgba(22, 32, 46, 0.55);\n}\n.pt-crumb em {\n  font-style: normal;\n  opacity: 0.6;\n}\n.pt-hero__grid {\n  display: grid;\n  grid-template-columns: 1.08fr 0.92fr;\n  gap: 2.6rem;\n  align-items: center;\n}\n.pt-hero__h2 {\n  margin: 0 0 0.6rem;\n  font-size: 1.35rem;\n  font-weight: 700;\n  line-height: 1.3;\n  color: var(--ledger, #0e6b52);\n}\n.pt-chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.5rem;\n  margin: 1.3rem 0 1rem;\n}\n.pt-chips span {\n  padding: 0.42rem 0.95rem;\n  border-radius: 999px;\n  background: #fff;\n  border: 1px solid rgba(14, 107, 82, 0.2);\n  font-size: 0.86rem;\n  font-weight: 600;\n  color: var(--ledger, #0e6b52);\n  opacity: 0;\n  animation: pt-rise 0.5s ease forwards;\n}\n.pt-ticks {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.45rem 1.4rem;\n  font-size: 0.85rem;\n  color: rgba(22, 32, 46, 0.68);\n}\n.pt-ticks li::before {\n  content: \"\\2713\\00a0\";\n  color: var(--ledger, #0e6b52);\n  font-weight: 700;\n}\n\n/* ---- Form --------------------------------------------------------------- */\n.pt-form {\n  padding: 1.6rem;\n  border-radius: 20px;\n  background: #fff;\n  border: 1px solid rgba(14, 107, 82, 0.15);\n  box-shadow: 0 18px 44px rgba(14, 107, 82, 0.1);\n}\n.pt-form h2 {\n  margin: 0;\n  font-size: 1.3rem;\n}\n.pt-form__sub {\n  margin: 0.3rem 0 1.2rem;\n  font-size: 0.88rem;\n  color: rgba(22, 32, 46, 0.65);\n}\n.pt-field {\n  display: block;\n  margin-bottom: 0.95rem;\n}\n.pt-field > span {\n  display: block;\n  margin-bottom: 0.35rem;\n  font-size: 0.82rem;\n  font-weight: 600;\n  color: rgba(22, 32, 46, 0.75);\n}\n.pt-field input {\n  width: 100%;\n  padding: 0.72rem 0.9rem;\n  border-radius: 11px;\n  border: 1px solid rgba(14, 107, 82, 0.22);\n  background: #fff;\n  font: inherit;\n  font-size: 0.95rem;\n  color: var(--ink, #16202e);\n  transition: border-color 0.15s ease, box-shadow 0.15s ease;\n}\n.pt-field input:focus {\n  outline: none;\n  border-color: var(--ledger, #0e6b52);\n  box-shadow: 0 0 0 3px rgba(14, 107, 82, 0.14);\n}\n.pt-field__phone {\n  display: flex;\n  align-items: stretch;\n  border-radius: 11px;\n  border: 1px solid rgba(14, 107, 82, 0.22);\n  overflow: hidden;\n  transition: border-color 0.15s ease, box-shadow 0.15s ease;\n}\n.pt-field__phone:focus-within {\n  border-color: var(--ledger, #0e6b52);\n  box-shadow: 0 0 0 3px rgba(14, 107, 82, 0.14);\n}\n.pt-field__phone em {\n  display: flex;\n  align-items: center;\n  padding: 0 0.75rem;\n  font-style: normal;\n  font-size: 0.92rem;\n  font-weight: 600;\n  background: var(--wash, #eef5f1);\n  color: var(--ledger, #0e6b52);\n}\n.pt-field__phone input {\n  border: 0;\n  border-radius: 0;\n  flex: 1;\n  min-width: 0;\n}\n.pt-field__phone input:focus {\n  box-shadow: none;\n}\n.pt-form__err {\n  margin: 0 0 0.8rem;\n  font-size: 0.84rem;\n  font-weight: 600;\n  color: #b4231f;\n}\n.pt-form__btn {\n  width: 100%;\n  justify-content: center;\n}\n.pt-form--done {\n  text-align: center;\n}\n.pt-form__tick {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 54px;\n  height: 54px;\n  padding: 13px;\n  margin-bottom: 0.8rem;\n  border-radius: 50%;\n  background: var(--ledger, #0e6b52);\n  color: #fff;\n  animation: pt-rise 0.4s ease;\n}\n.pt-form__tick svg {\n  width: 100%;\n  height: 100%;\n}\n\n/* ---- Hover lift on cards ------------------------------------------------ */\n.pt-lift {\n  transition: transform 0.18s ease, box-shadow 0.18s ease;\n}\n.pt-lift:hover {\n  transform: translateY(-4px);\n  box-shadow: 0 14px 30px rgba(14, 107, 82, 0.12);\n}\n\n/* ---- 3. CA points ------------------------------------------------------- */\n.pt-points {\n  list-style: none;\n  margin: 1.5rem 0;\n  padding: 0;\n  display: grid;\n  gap: 1rem;\n}\n.pt-points li {\n  display: flex;\n  gap: 0.8rem;\n  opacity: 0;\n  animation: pt-rise 0.5s ease forwards;\n}\n.pt-points__tick {\n  flex: none;\n  width: 26px;\n  height: 26px;\n  padding: 5px;\n  margin-top: 2px;\n  border-radius: 50%;\n  background: var(--ledger, #0e6b52);\n  color: #fff;\n}\n.pt-points__tick svg {\n  width: 100%;\n  height: 100%;\n}\n.pt-points strong {\n  display: block;\n  font-size: 1rem;\n}\n.pt-points p {\n  margin: 0.15rem 0 0;\n  font-size: 0.92rem;\n  color: rgba(22, 32, 46, 0.72);\n}\n.pt-foot {\n  margin-top: 0.9rem;\n  font-size: 0.84rem;\n  color: rgba(22, 32, 46, 0.6);\n}\n\n/* ---- 5. Steps ----------------------------------------------------------- */\n.pt-steps {\n  list-style: none;\n  margin: 2.6rem 0 2rem;\n  padding: 0;\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));\n  gap: 1.1rem;\n}\n.pt-step {\n  position: relative;\n  padding: 2rem 1.3rem 1.3rem;\n  border-radius: 18px;\n  background: #fff;\n  border: 1px solid rgba(14, 107, 82, 0.13);\n  overflow: hidden;\n}\n.pt-step__no {\n  position: absolute;\n  top: -0.5rem;\n  right: 0.6rem;\n  font-size: 3.4rem;\n  font-weight: 800;\n  line-height: 1;\n  color: var(--pt-accent-soft);\n  pointer-events: none;\n}\n.pt-step h3 {\n  margin: 0 0 0.4rem;\n  font-size: 1.08rem;\n}\n.pt-step p {\n  margin: 0;\n  font-size: 0.93rem;\n}\n\n/* ==========================================================================\n   6. SUCCESS STORIES  (the design from the screenshot)\n   ========================================================================== */\n.pt-underline {\n  position: relative;\n  display: inline-block;\n  padding-bottom: 0.45rem;\n}\n.pt-underline::after {\n  content: \"\";\n  position: absolute;\n  left: 12%;\n  right: 12%;\n  bottom: 0;\n  height: 4px;\n  border-radius: 2px;\n  background: var(--marigold, #f2a20c);\n  transform-origin: left;\n  animation: pt-grow 0.6s ease forwards;\n}\n\n.pt-regions {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  max-width: 760px;\n  margin: 2.2rem auto 2rem;\n  border-radius: 14px;\n  background: var(--pt-accent-soft);\n  overflow: hidden;\n}\n.pt-region {\n  padding: 0.95rem 0.6rem;\n  border: 0;\n  background: transparent;\n  font: inherit;\n  font-size: 1.02rem;\n  font-weight: 600;\n  color: var(--ink, #16202e);\n  cursor: pointer;\n  transition: background 0.18s ease, color 0.18s ease;\n}\n.pt-region:hover {\n  background: rgba(14, 107, 82, 0.12);\n}\n.pt-region.is-on {\n  background: var(--pt-accent);\n  color: #fff;\n}\n\n.pt-stories {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(330px, 1fr));\n  gap: 1.6rem;\n}\n.pt-story {\n  display: grid;\n  grid-template-columns: 180px 1fr;\n  align-items: stretch;\n  opacity: 0;\n  animation: pt-slide 0.5s ease forwards;\n}\n.pt-story__side {\n  padding: 1.3rem 1rem;\n  border-radius: 16px;\n  background: var(--pt-accent);\n  color: #fff;\n  text-align: center;\n  position: relative;\n  z-index: 2;\n  box-shadow: 0 10px 26px rgba(14, 107, 82, 0.22);\n}\n.pt-art.pt-story__pic {\n  width: 92px;\n  height: 92px;\n  margin: 0 auto 0.7rem;\n}\n.pt-art .art.pt-avatar {\n  width: 92px;\n  height: 92px;\n}\n.pt-story__name {\n  margin: 0;\n  font-size: 0.98rem;\n  font-weight: 700;\n  line-height: 1.25;\n}\n.pt-story__role {\n  margin: 0.15rem 0 0.8rem;\n  font-size: 0.82rem;\n  opacity: 0.85;\n}\n.pt-story__amount {\n  display: inline-block;\n  padding: 0.42rem 0.9rem;\n  border-radius: 999px;\n  background: #fff;\n  color: var(--pt-accent);\n  font-size: 0.86rem;\n  font-weight: 700;\n  white-space: nowrap;\n}\n.pt-story__body {\n  display: flex;\n  align-items: center;\n  margin: 1rem 0 1rem -14px;\n  padding: 1.4rem 1.4rem 1.4rem 2.2rem;\n  border-radius: 0 16px 16px 0;\n  background: #fff;\n  border: 1px solid rgba(14, 107, 82, 0.13);\n  border-left: 0;\n  box-shadow: 0 8px 22px rgba(14, 107, 82, 0.07);\n}\n.pt-story__body p {\n  margin: 0;\n  font-size: 0.95rem;\n  line-height: 1.6;\n  color: rgba(22, 32, 46, 0.82);\n}\n.pt-stories__cta {\n  margin-top: 2.2rem;\n}\n\n/* ---- 8. Calculator ------------------------------------------------------ */\n.pt-calc {\n  display: grid;\n  grid-template-columns: 1.05fr 0.95fr;\n  gap: 1.4rem;\n  margin-top: 2.4rem;\n  align-items: stretch;\n}\n.pt-calc__box,\n.pt-get {\n  padding: 1.6rem;\n  border-radius: 20px;\n  background: #fff;\n  border: 1px solid rgba(14, 107, 82, 0.15);\n}\n.pt-get {\n  background: var(--wash, #eef5f1);\n}\n.pt-calc__box h3,\n.pt-get h3 {\n  margin: 0;\n  font-size: 1.2rem;\n}\n.pt-calc__sub {\n  margin: 0.3rem 0 1.5rem;\n  font-size: 0.88rem;\n  color: rgba(22, 32, 46, 0.65);\n}\n.pt-calc__label {\n  display: flex;\n  justify-content: space-between;\n  align-items: baseline;\n  font-size: 0.88rem;\n  font-weight: 600;\n  color: rgba(22, 32, 46, 0.75);\n}\n.pt-calc__label strong {\n  font-size: 1.4rem;\n  color: var(--ledger, #0e6b52);\n}\n\n.pt-range {\n  -webkit-appearance: none;\n  appearance: none;\n  width: 100%;\n  height: 8px;\n  margin: 0.7rem 0 0.3rem;\n  border-radius: 999px;\n  background: linear-gradient(\n    to right,\n    var(--ledger, #0e6b52) var(--pt-pct, 10%),\n    rgba(14, 107, 82, 0.15) var(--pt-pct, 10%)\n  );\n  cursor: pointer;\n}\n.pt-range::-webkit-slider-thumb {\n  -webkit-appearance: none;\n  appearance: none;\n  width: 24px;\n  height: 24px;\n  border-radius: 50%;\n  background: #fff;\n  border: 4px solid var(--ledger, #0e6b52);\n  box-shadow: 0 3px 10px rgba(14, 107, 82, 0.3);\n  transition: transform 0.15s ease;\n}\n.pt-range::-webkit-slider-thumb:hover {\n  transform: scale(1.12);\n}\n.pt-range::-moz-range-thumb {\n  width: 22px;\n  height: 22px;\n  border-radius: 50%;\n  background: #fff;\n  border: 4px solid var(--ledger, #0e6b52);\n  box-shadow: 0 3px 10px rgba(14, 107, 82, 0.3);\n}\n.pt-calc__ends {\n  display: flex;\n  justify-content: space-between;\n  font-size: 0.78rem;\n  color: rgba(22, 32, 46, 0.5);\n}\n\n.pt-calc__out {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));\n  gap: 0.9rem;\n  margin: 1.4rem 0 0.9rem;\n}\n.pt-calc__out > div {\n  padding: 1rem 1.1rem;\n  border-radius: 14px;\n  background: var(--wash, #eef5f1);\n}\n.pt-calc__out span {\n  display: block;\n  font-size: 0.8rem;\n  color: rgba(22, 32, 46, 0.62);\n}\n.pt-calc__out strong {\n  display: block;\n  margin-top: 0.2rem;\n  font-size: 1.55rem;\n  line-height: 1.15;\n  color: var(--ledger, #0e6b52);\n  font-variant-numeric: tabular-nums;\n}\n.pt-calc__note {\n  margin: 0;\n  font-size: 0.78rem;\n  color: rgba(22, 32, 46, 0.55);\n}\n\n.pt-get ul {\n  list-style: none;\n  margin: 1.2rem 0 0;\n  padding: 0;\n  display: grid;\n  gap: 0.75rem;\n}\n.pt-get li {\n  display: flex;\n  align-items: flex-start;\n  gap: 0.7rem;\n  font-size: 0.94rem;\n  opacity: 0;\n  animation: pt-rise 0.5s ease forwards;\n}\n.pt-get li span {\n  flex: none;\n  width: 24px;\n  height: 24px;\n  padding: 5px;\n  border-radius: 50%;\n  background: var(--ledger, #0e6b52);\n  color: #fff;\n}\n.pt-get li span svg {\n  width: 100%;\n  height: 100%;\n}\n\n/* ---- Responsive --------------------------------------------------------- */\n@media (max-width: 900px) {\n  .pt-hero__grid,\n  .pt-calc {\n    grid-template-columns: 1fr;\n  }\n  .pt-regions {\n    grid-template-columns: repeat(2, 1fr);\n  }\n  .pt-stories {\n    grid-template-columns: 1fr;\n  }\n}\n\n@media (max-width: 560px) {\n  .pt-story {\n    grid-template-columns: 1fr;\n  }\n  .pt-story__body {\n    margin: -14px 0 0;\n    padding: 2rem 1.2rem 1.3rem;\n    border-radius: 0 0 16px 16px;\n    border-left: 1px solid rgba(14, 107, 82, 0.13);\n    border-top: 0;\n  }\n  .pt-step__no {\n    font-size: 2.8rem;\n  }\n}\n\n/* keeps the eyebrow on its own line instead of hugging the heading */\n.pt-eyebrow {\n  display: block;\n  margin-bottom: 0.35rem;\n}\n\n/* ==========================================================================\n   4. PRODUCT CONFIDENCE CARDS  (the screenshot design)\n   ========================================================================== */\n.pt-product {\n  background: linear-gradient(180deg, #fff 0%, var(--wash, #eef5f1) 100%);\n}\n\n/* small rounded pill above the heading */\n.pt-pill {\n  display: inline-block;\n  margin-bottom: 1rem;\n  padding: 0.42rem 1.1rem;\n  border-radius: 999px;\n  background: var(--pt-accent-soft);\n  color: var(--pt-accent);\n  font-size: 0.72rem;\n  font-weight: 700;\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n}\n\n.pt-product__h2 {\n  margin-top: 0;\n}\n\n/* highlighted second half of the heading, with the underline */\n.pt-mark {\n  position: relative;\n  display: inline-block;\n  color: var(--pt-accent);\n  padding-bottom: 0.3rem;\n  white-space: nowrap;\n}\n.pt-mark::after {\n  content: \"\";\n  position: absolute;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  height: 3px;\n  border-radius: 2px;\n  background: var(--pt-accent);\n  transform-origin: left;\n  animation: pt-grow 0.6s ease 0.15s both;\n}\n\n.pt-cards {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));\n  gap: 1.1rem;\n  margin-top: 2.6rem;\n}\n.pt-card {\n  height: 100%;\n  padding: 1.1rem 1.1rem 1.4rem;\n  border-radius: 18px;\n  background: #fff;\n  border: 1px solid rgba(22, 32, 46, 0.1);\n  transition: transform 0.18s ease, box-shadow 0.18s ease;\n}\n.pt-card:hover {\n  transform: translateY(-5px);\n  box-shadow: 0 16px 34px rgba(14, 107, 82, 0.12);\n}\n.pt-card__shot {\n  padding: 0.9rem;\n  margin-bottom: 1.2rem;\n  border-radius: 14px;\n  background: var(--wash, #eef5f1);\n}\n.pt-card__shot .pt-art,\n.pt-card__shot .pt-shot,\n.pt-card__shot .pt-shot__img {\n  display: block;\n  width: 100%;\n}\n.pt-card__shot .pt-shot {\n  min-height: 130px;\n}\n.pt-cardart {\n  display: block;\n  width: 100%;\n  height: auto;\n}\n.pt-card h3 {\n  margin: 0 0 0.4rem;\n  font-size: 1.02rem;\n}\n.pt-card p {\n  margin: 0;\n  font-size: 0.9rem;\n  line-height: 1.55;\n  color: rgba(22, 32, 46, 0.68);\n}\n.pt-cards__cta {\n  margin-top: 2.4rem;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .pt-mark::after {\n    animation: none;\n    transform: none;\n  }\n}\n\n/* ==========================================================================\n   FOUR-ACROSS CARD GRID  (.pt-quad + .pt-qcard)\n   --------------------------------------------------------------------------\n   The shared .fgrid uses auto-fit, which wrapped these four cards as 3 + 1.\n   This grid pins them to one row on desktop, two per row on tablet and one\n   on phones, and the cards are more compact so four fit comfortably.\n   ========================================================================== */\n.pt-quad {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  gap: 0.9rem;\n  margin-top: 2.4rem;\n  align-items: stretch;\n}\n\n/* Reveal wraps each card, so the wrapper has to stretch too */\n.pt-quad > * {\n  display: flex;\n  height: 100%;\n}\n\n.pt-qcard {\n  position: relative;\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  padding: 1.5rem 1.1rem 1.2rem;\n  border-radius: 16px;\n  background: #fff;\n  border: 1px solid rgba(22, 32, 46, 0.1);\n  overflow: hidden;\n  transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;\n}\n\n/* the accent bar across the top, which slides in on hover */\n.pt-qcard__bar {\n  position: absolute;\n  inset: 0 0 auto 0;\n  height: 3px;\n  background: linear-gradient(90deg, var(--pt-accent), var(--marigold, #f2a20c));\n  transform: scaleX(0);\n  transform-origin: left;\n  transition: transform 0.3s ease;\n}\n\n.pt-qcard:hover {\n  transform: translateY(-6px);\n  border-color: rgba(14, 107, 82, 0.25);\n  box-shadow: 0 18px 36px rgba(14, 107, 82, 0.13);\n}\n.pt-qcard:hover .pt-qcard__bar {\n  transform: scaleX(1);\n}\n\n.pt-qcard__icon {\n  display: inline-flex;\n  width: 42px;\n  height: 42px;\n  padding: 9px;\n  margin-bottom: 0.85rem;\n  border-radius: 12px;\n  background: var(--pt-accent-soft);\n  color: var(--pt-accent);\n  transition: transform 0.25s ease, background 0.25s ease, color 0.25s ease;\n}\n.pt-qcard__icon svg {\n  width: 100%;\n  height: 100%;\n}\n.pt-qcard:hover .pt-qcard__icon {\n  transform: translateY(-2px) rotate(-6deg) scale(1.06);\n  background: var(--pt-accent);\n  color: #fff;\n}\n\n.pt-qcard h3 {\n  margin: 0 0 0.4rem;\n  font-size: 0.98rem;\n  line-height: 1.3;\n}\n.pt-qcard p {\n  margin: 0;\n  font-size: 0.86rem;\n  line-height: 1.55;\n  color: rgba(22, 32, 46, 0.68);\n}\n\n/* faint number watermark, used on the \"Why Become a Partner\" cards */\n.pt-qcard--num::after {\n  content: attr(data-num);\n  position: absolute;\n  right: 0.7rem;\n  bottom: -0.55rem;\n  font-size: 3.1rem;\n  font-weight: 800;\n  line-height: 1;\n  color: rgba(14, 107, 82, 0.07);\n  pointer-events: none;\n  transition: color 0.25s ease, transform 0.25s ease;\n}\n.pt-qcard--num:hover::after {\n  color: rgba(14, 107, 82, 0.13);\n  transform: translateY(-3px);\n}\n\n@media (max-width: 1040px) {\n  .pt-quad {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n}\n@media (max-width: 560px) {\n  .pt-quad {\n    grid-template-columns: 1fr;\n  }\n}\n@media (prefers-reduced-motion: reduce) {\n  .pt-qcard,\n  .pt-qcard__bar,\n  .pt-qcard__icon,\n  .pt-qcard--num::after {\n    transition: none;\n  }\n}\n",
  "app/partner/page.js": "import PartnerPage, { partnerMeta, partnerFaqs } from \"@/components/partner/Page\";\nimport { pageMeta } from \"@/lib/seo\";\n\nexport const metadata = pageMeta({\n  title: partnerMeta.title,\n  description: partnerMeta.description,\n  path: \"/partner\",\n});\n\nconst faqSchema = {\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"FAQPage\",\n  mainEntity: partnerFaqs.map(([q, a]) => ({\n    \"@type\": \"Question\",\n    name: q,\n    acceptedAnswer: { \"@type\": \"Answer\", text: a },\n  })),\n};\n\nexport default function Page() {\n  return (\n    <>\n      <script\n        type=\"application/ld+json\"\n        dangerouslySetInnerHTML={{ __html: JSON.stringify(faqSchema) }}\n      />\n      <PartnerPage />\n    </>\n  );\n}\n"
};

let written = 0;

for (const [rel, body] of Object.entries(FILES)) {
  const dest = path.join(root, rel);
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  if (fs.existsSync(dest) && !fs.existsSync(dest + ".bak")) {
    fs.copyFileSync(dest, dest + ".bak");
    console.log("  backup  " + rel + ".bak");
  }
  fs.writeFileSync(dest, body, "utf8");
  console.log("  write   " + rel);
  written++;
}

const g = path.join(root, "app", "globals.css");
const IMPORT = '@import "../components/partner/partner.css";';

if (fs.existsSync(g)) {
  let css = fs.readFileSync(g, "utf8");
  if (css.includes("components/partner/partner.css")) {
    console.log("  skip    app/globals.css (import already there)");
  } else {
    const lines = css.split("\n");
    let at = -1;
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].trim().startsWith("@import")) at = i;
    }
    lines.splice(at + 1, 0, IMPORT);
    fs.writeFileSync(g, lines.join("\n"), "utf8");
    console.log("  patch   app/globals.css  (added the partner.css import)");
  }
} else {
  console.log("\n  NOTE: app/globals.css was not found.");
  console.log("  Add this line to your global css file yourself:");
  console.log("      " + IMPORT);
}

console.log("\n  Done - " + written + " files written.");
console.log("  Now run:  npm run dev     and open  /partner\n");
